    hosts = payload.get("hosts") or []
    program = payload.get("program") or {}
    result = {}
    for host in hosts:
        table = {}
        for s, stage in enumerate(STAGES):
            items = program.get(stage) or []
            for i, item in enumerate(items):
                _walk(item, "%d/%d" % (s, i), host, table)
