"""host_conditions: per-host node table of [executable, will_fail] by tree position.

Tree positions are integer levels joined by "/". The five program stages are
pre/roles/includes/tasks/post (indices 0..4). Within a block, the normal,
rescue and always branches are indices 0/1/2 respectively.
"""

STAGES = ("pre", "roles", "includes", "tasks", "post")


def _satisfies(only, host):
    return only is None or host in only


def _walk(item, path, host, table):
    if isinstance(item, dict) and "block" in item:
        only = item.get("only")
        table[path] = [_satisfies(only, host), False]
        block = item["block"]
        for branch, key in enumerate(("tasks", "rescue", "always")):
            for j, sub in enumerate(block.get(key, []) or []):
                _walk(sub, "%s/%d/%d" % (path, branch, j), host, table)
    else:
        only = item.get("only")
        fail_hosts = item.get("fail_hosts") or []
        table[path] = [_satisfies(only, host), host in fail_hosts]


def compute(payload):
    """每个 host 对应一张节点表，按树位置（各级整数以 / 分隔）记录 [可执行,会失败]；包含块节点。"""
    hosts = payload.get("hosts") or []
    program = payload.get("program") or {}
    result = {}
    for host in hosts:
        table = {}
        for s, stage in enumerate(STAGES):
            items = program.get(stage) or []
            for i, item in enumerate(items):
                _walk(item, "%d/%d" % (s, i), host, table)
        result[host] = table
    return result

STAGES = ("pre", "roles", "includes", "tasks", "post")


def _is_block(item):
    return isinstance(item, dict) and "block" in item


def _is_task(item):
    return isinstance(item, dict) and "id" in item


def compute(payload):
    """输出 [处理器声明顺序映射,叶节点到通知清单的映射]。

    叶节点按同一树位置编码；通知名去重并按声明顺序排列，含 rescue、always。
    """
    handlers = payload.get("handlers", [])
    program = payload.get("program", {})

    handler_order = {name: idx for idx, name in enumerate(handlers)}

    leaf_to_notify = {}

    for stage_idx, stage_name in enumerate(STAGES):
        items = program.get(stage_name, [])
        if not isinstance(items, list):
            continue
        for item_idx, item in enumerate(items):
            if _is_task(item):
                path = "%d/%d" % (stage_idx, item_idx)
                notify = item.get("notify", [])
                if notify:
                    leaf_to_notify[path] = _ordered_notify(notify, handler_order)
            elif _is_block(item):
                block = item["block"]
                for branch_idx, branch_name in enumerate(("tasks", "rescue", "always")):
                    branch = block.get(branch_name, [])
                    if not isinstance(branch, list):
                        continue
                    for task_idx, task in enumerate(branch):
                        if not _is_task(task):
                            continue
                        path = "%d/%d/%d/%d" % (stage_idx, item_idx, branch_idx, task_idx)
                        notify = task.get("notify", [])
                        if notify:
                            leaf_to_notify[path] = _ordered_notify(notify, handler_order)

    return [handler_order, leaf_to_notify]


def _ordered_notify(notify, handler_order):
    seen = set()
    result = []
    for name in notify:
        if name in seen:
            continue
        seen.add(name)
        result.append(name)
    result.sort(key=lambda n: handler_order.get(n, len(handler_order)))
    return result

STAGES = ("pre", "roles", "includes", "tasks", "post")


def _is_block(item):
    return isinstance(item, dict) and "block" in item


def _is_task(item):
    return isinstance(item, dict) and "id" in item


def compute(payload):
    """输出 [处理器声明顺序映射,叶节点到通知清单的映射]。

    叶节点按同一树位置编码；通知名去重并按声明顺序排列，含 rescue、always。
    """
    handlers = payload.get("handlers", [])
    program = payload.get("program", {})

    handler_order = {name: idx for idx, name in enumerate(handlers)}

    leaf_to_notify = {}

    for stage_idx, stage_name in enumerate(STAGES):
        items = program.get(stage_name, [])
        if not isinstance(items, list):
            continue
        for item_idx, item in enumerate(items):
            if _is_task(item):
                path = "%d/%d" % (stage_idx, item_idx)
                notify = item.get("notify", [])
                if notify:
                    leaf_to_notify[path] = _ordered_notify(notify, handler_order)
            elif _is_block(item):
                block = item["block"]
                for branch_idx, branch_name in enumerate(("tasks", "rescue", "always")):
                    branch = block.get(branch_name, [])
                    if not isinstance(branch, list):
                        continue
                    for task_idx, task in enumerate(branch):
                        if not _is_task(task):
                            continue
                        path = "%d/%d/%d/%d" % (stage_idx, item_idx, branch_idx, task_idx)
                        notify = task.get("notify", [])
                        if notify:
                            leaf_to_notify[path] = _ordered_notify(notify, handler_order)

    return [handler_order, leaf_to_notify]


def _ordered_notify(notify, handler_order):
    seen = set()
