import json
import sys
import unittest
from pathlib import Path

root = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(root))

from components.host_conditions.work import compute


class TestHostConditions(unittest.TestCase):
    def test_empty_program(self):
        payload = {"hosts": ["h0", "h1"], "program": {}}
        self.assertEqual(compute(payload), {"h0": {}, "h1": {}})

    def test_task_and_block(self):
        payload = {
            "hosts": ["h0", "h1"],
            "program": {
                "tasks": [
                    {"id": "t1", "only": ["h0"], "fail_hosts": ["h1"], "notify": ["n1"]},
                    {"block": {
                        "tasks": [{"id": "t2", "fail_hosts": ["h0"]}],
                        "rescue": [{"id": "t3"}],
                        "always": [{"id": "t4"}],
                    }, "only": ["h0", "h1"]},
                ]
            },
        }
        out = compute(payload)
        self.assertEqual(out["h0"], {
            "3/0": [True, False],
            "3/1": [True, False],
            "3/1/0/0": [True, True],
            "3/1/1/0": [True, False],
            "3/1/2/0": [True, False],
        })
        self.assertEqual(out["h1"], {
            "3/0": [False, True],
