def _is_block(item):
    return isinstance(item, dict) and "block" in item


def _is_task(item):
    return isinstance(item, dict) and "id" in item


def _satisfies(only, host):
    return only is None or host in only


def _path_key(path):
    return tuple(int(x) for x in path.split("/"))


def _walk(item, path, host, table, leaf_notify):
    """Return list of node descriptors in canonical pre-order for one host.

    Each descriptor is a dict with keys: path, kind ('task'|'block'),
    branch (None for top-level, 0/1/2 for block branches), and for tasks
    the task dict itself.
    """
    if _is_block(item):
        only = item.get("only")
        executable = _satisfies(only, host)
        block = item["block"]
