    hosts = payload.get("hosts") or []
    handlers = payload.get("handlers") or []
    handler_order = right[0] if isinstance(right, list) and right else {}
    leaf_notify = right[1] if isinstance(right, list) and len(right) > 1 else {}

    program = payload.get("program") or {}

    # Build per-host execution plan: a list of "events" in canonical order.
    # Each event is a node (task or block) plus a flush marker at stage end.
    # We simulate the linear strategy by tracking, for each host, its next
    # event index and the set of hosts that are "ready" (not yet failed and
    # not yet finished).

