            stage_nodes = []
            for i, item in enumerate(items):
                stage_nodes.extend(_walk(item, "%d/%d" % (s, i), host, table, leaf_notify))
            events.append((s, stage_nodes))
        host_events[host] = events

    # Per-host state.
    state = {}
    for host in hosts:
        state[host] = {
            "stage_idx": 0,
            "node_idx": 0,
            "failed": False,
            "pending": [],  # notify names accumulated in current stage
            "done": False,
            "block_skip": None,  # None or set of paths to skip (block normal tasks)
        }

