        advancing = [h for h in hosts if h in ready and pos_key(ready[h]) == min_key]

        for host in advancing:
            n = ready[host]
            st = state[host]
            if n[0] == "flush":
                s = n[1]
                # Flush pending notifications for this stage.
                if st["pending"]:
                    # dedupe preserving order
                    seen = set()
                    names = []
                    for name in st["pending"]:
                        if name not in seen:
                            seen.add(name)
                            names.append(name)
                    # order by handler declaration
                    names.sort(key=lambda nm: handler_order.get(nm, len(handlers)))
                    batches.append({
                        "host": host,
                        "task": None,
                        "kind": "flush",
                        "status": "ok",
                        "handlers": names,
                    })
                    for nm in names:
                        batches.append({
                            "host": host,
                            "task": nm,
                            "kind": "handler",
                            "status": "ok",
                        })
                    st["pending"] = []
                st["stage_idx"] += 1
                st["node_idx"] = 0
            else:
                s, idx, node = n
                st["node_idx"] = idx + 1
                if node["kind"] == "block":
                    # Block node: just advance (no output pair for block itself).
                    # The block's children are separate nodes already in the list.
                    continue
                # task node
                task = node["task"]
                executable = node["executable"]
                will_fail = node["will_fail"]
                if not executable:
                    # Task not run (only not satisfied): skip, no output.
                    continue
                # Run the task.
                if will_fail:
                    status = "failed"
                else:
                    status = "ok"
                batches.append({
                    "host": host,
                    "task": task.get("id"),
                    "kind": "task",
                    "status": status,
                })
                if status == "ok":
                    # accumulate notify
                    for nm in task.get("notify") or []:
                        st["pending"].append(nm)
                else:
                    # failure: need to handle block rescue/always semantics.
                    # This is handled by the block-level simulation; for now
                    # mark host failed unless rescue recovers.
                    st["failed"] = True
                    final[host] = "failed"

    return {"batches": batches, "final": final}

