            stage_nodes = []
            for i, item in enumerate(items):
                stage_nodes.extend(_walk(item, "%d/%d" % (s, i), host, table))
            events.append((s, stage_nodes))
        host_events[host] = events

    # Per-host state.
    state = {}
    for host in hosts:
        state[host] = {
            "stage_idx": 0,
            "node_idx": 0,
            "failed": False,
            "pending": [],
            "done": False,
        }

    batches = []
    final = {h: "ok" for h in hosts}

